# Generated by joobqui-selfhosted sdk:generate from templates/sdks/elixir/test/joobq/job_test.exs.j2. DO NOT EDIT.
defmodule JoobQ.JobTest do
  use ExUnit.Case, async: true

  alias JoobQ.Job

  test "sends only the queue, the type and the payload by default" do
    assert Job.body("mail", "welcome") == %{
             "queue" => "mail",
             "job_type" => "welcome",
             "payload" => %{}
           }
  end

  test "sends the options it is given, under the gateway's names" do
    body =
      Job.body("mail", "welcome", %{"to" => "a@b.c"},
        jid: "j1",
        context: %{"tenant_id" => "t1"},
        max_retries: 0,
        delay_ms: 500,
        run_at_ms: 1_700_000_000_000
      )

    assert body == %{
             "queue" => "mail",
             "job_type" => "welcome",
             "payload" => %{"to" => "a@b.c"},
             "jid" => "j1",
             "context" => %{"tenant_id" => "t1"},
             "max_retries" => 0,
             "delay_ms" => 500,
             "run_at_ms" => 1_700_000_000_000
           }
  end

  test "turns scheduled_at into run_at_ms and leaves nil options out" do
    at = ~U[2026-11-16 12:00:00.250Z]
    assert Job.body("q", "t", %{}, scheduled_at: at, jid: nil)["run_at_ms"] == 1_794_830_400_250
    refute Map.has_key?(Job.body("q", "t", %{}, jid: nil), "jid")
  end

  test "refuses a wrong option, naming it" do
    assert_raise ArgumentError, ~r/:queue/, fn -> Job.body("", "t") end

    assert_raise ArgumentError, ~r/:max_retries/, fn ->
      Job.body("q", "t", %{}, max_retries: 101)
    end

    assert_raise ArgumentError, ~r/:delay_ms/, fn -> Job.body("q", "t", %{}, delay_ms: -1) end
    assert_raise ArgumentError, ~r/:context/, fn -> Job.body("q", "t", %{}, context: [a: 1]) end

    assert_raise ArgumentError, ~r/:scheduled_at/, fn ->
      Job.body("q", "t", %{}, scheduled_at: "soon")
    end

    assert_raise ArgumentError, ~r/:scheduled_at/, fn ->
      Job.body("q", "t", %{}, scheduled_at: DateTime.utc_now(), run_at_ms: 1)
    end

    assert_raise ArgumentError, fn -> Job.body("q", "t", %{}, snooze: 1) end
  end

  test "sends the deadlines, which must be positive" do
    body = Job.body("q", "t", %{}, expires_ms: 60_000, timeout_ms: 5_000)
    assert {body["expires_ms"], body["timeout_ms"]} == {60_000, 5_000}
    assert_raise ArgumentError, ~r/:expires_ms/, fn -> Job.body("q", "t", %{}, expires_ms: 0) end

    assert_raise ArgumentError, ~r/:timeout_ms/, fn ->
      Job.body("q", "t", %{}, timeout_ms: 1.5)
    end
  end

  test "sends the idempotency key, its lifetime and its mode" do
    body =
      Job.body("q", "t", %{},
        unique_key: "order-7",
        unique_ttl_ms: 60_000,
        unique_mode: :until_executed
      )

    assert Map.take(body, ["unique_key", "unique_ttl_ms", "unique_mode"]) == %{
             "unique_key" => "order-7",
             "unique_ttl_ms" => 60_000,
             "unique_mode" => "until_executed"
           }

    assert Job.body("q", "t", %{}, unique_mode: "while_locked")["unique_mode"] == "while_locked"

    assert_raise ArgumentError, ~r/:unique_mode/, fn ->
      Job.body("q", "t", %{}, unique_mode: :forever)
    end

    assert_raise ArgumentError, ~r/:unique_key/, fn -> Job.body("q", "t", %{}, unique_key: "") end
  end

  test "names the fields the gateway seals" do
    assert Job.body("q", "t", %{}, encrypt_fields: [:card, "iban"])["encrypt_fields"] == [
             "card",
             "iban"
           ]

    assert_raise ArgumentError, ~r/:encrypt_fields/, fn ->
      Job.body("q", "t", %{}, encrypt_fields: "card")
    end
  end

  test "an error never repeats the value it refuses" do
    for refused <- [
          fn -> Job.body("q", "t", %{}, context: [token: "s3cr3t"]) end,
          fn -> Job.body("q", "t", %{}, unique_key: ["s3cr3t"]) end,
          fn -> Job.batches([{"q", "t", %{"card" => "s3cr3t"}, :not_options}]) end
        ] do
      error = assert_raise ArgumentError, refused
      refute error.message =~ "s3cr3t"
    end

    error = assert_raise ArgumentError, fn -> Job.body("q", "t", %{}, context: [a: 1]) end
    assert error.message == "JoobQ job option :context must be a map, got a list"
  end

  test "batches cuts the jobs into calls of at most 500, in order" do
    jobs = for n <- 1..1001, do: {"q", "t", %{"n" => n}}
    batches = Job.batches(jobs)
    assert Enum.map(batches, &length/1) == [500, 500, 1]
    assert batches |> List.flatten() |> Enum.map(& &1["payload"]["n"]) == Enum.to_list(1..1001)
    assert Job.batches([]) == []
  end

  test "batches takes every job shape and gives the context to jobs without their own" do
    jobs = [
      {"q", "a"},
      {"q", "b", %{"x" => 1}},
      {"q", "c", %{}, context: %{"own" => true}, delay_ms: 5}
    ]

    [[a, b, c]] = Job.batches(jobs, %{"tenant_id" => "t1"})

    assert a == %{
             "queue" => "q",
             "job_type" => "a",
             "payload" => %{},
             "context" => %{"tenant_id" => "t1"}
           }

    assert b["payload"] == %{"x" => 1}
    assert b["context"] == %{"tenant_id" => "t1"}
    assert c["context"] == %{"own" => true}
    assert c["delay_ms"] == 5
    assert_raise ArgumentError, ~r/job/, fn -> Job.batches([:nope]) end
  end
end
